chooser.source:
if (attacktype == 0)
    rr = 0;

if (attacktype == 1)
    rr = 3;

if (attacktype == 2)
    rr = 1;

if (attacktype == 3)
    rr = 2;

dc = instance_create(x, y, obj_checkers_leap);
dc.leapmode = rr;
dc.target = mytarget;
dc.damage = global.monsterat[myself] * 5;
attacktype += 1;

if (attacktype > 3)
    attacktype = 0;
